CREATE OR REPLACE FUNCTION public.finish_collection()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare p public.profiles; found_count int; factor numeric; efficiency numeric; alcohol_factor numeric := 1.0; new_xp int; gained_xp int; nail_chance numeric; wood_chance numeric; shard_chance numeric; textile_chance numeric; found_nails int; found_wood int; found_shards int; found_textile int; begin select * into p from public.profiles where id=auth.uid() for update; if p.id is null or p.is_banned then raise exception 'Zugriff gesperrt'; end if; if p.collection_ends_at is null then raise exception 'Keine Pfandtour aktiv'; end if; if p.collection_ends_at>now() then raise exception 'Der Einkaufswagen ist noch unterwegs'; end if; factor := (array[1.0,1.25,1.55,1.95,2.5])[least(p.area_level,5)]; efficiency := case p.collection_minutes when 10 then 1.0 when 30 then 0.88 when 60 then 0.78 when 240 then 0.62 when 480 then 0.52 else 0.50 end; if p.alcohol_level >= 5 then alcohol_factor := 0.6; else alcohol_factor := 1 + least(p.alcohol_level,4.99)*0.15; end if; found_count := greatest(1,floor((p.collection_minutes/10.0)*(5+p.streetwise*0.8+(p.bag_level-1)*2)*factor*efficiency*alcohol_factor*(0.85+random()*0.30))::int); gained_xp := greatest(5,floor(p.collection_minutes/10.0)::int*2); new_xp := p.xp+gained_xp; nail_chance := least(0.35,0.10+p.collection_minutes/480.0*0.20); wood_chance := least(0.32,0.09+p.collection_minutes/480.0*0.18); shard_chance := least(0.10,0.02+p.collection_minutes/480.0*0.06); textile_chance := least(0.28,0.08+p.collection_minutes/480.0*0.16); found_nails := case when random()<nail_chance then 1 else 0 end; found_wood := case when random()<wood_chance then 1 else 0 end; found_shards := case when random()<shard_chance then 1 else 0 end; found_textile := case when random()<textile_chance then 1 else 0 end; update public.profiles set bottles=bottles+found_count, mat_nails=mat_nails+found_nails, mat_wood=mat_wood+found_wood, mat_shards=mat_shards+found_shards, mat_textile=mat_textile+found_textile, cleanliness=greatest(0,cleanliness-least(80,p.collection_minutes/10)), xp=new_xp, level=least(150,greatest(level,1+floor(new_xp/250)::int)), collection_started_at=null, collection_ends_at=null, collection_minutes=null, collection_ready_at=now()+interval '30 seconds' where id=auth.uid() returning * into p; insert into public.daily_missions(user_id,progress) values(auth.uid(),found_count) on conflict(user_id,mission_day) do update set progress=daily_missions.progress+excluded.progress; return jsonb_build_object('found',found_count,'xp',gained_xp,'alcohol_bonus',alcohol_factor,'nails',found_nails,'wood',found_wood,'shards',found_shards,'textile',found_textile,'profile',to_jsonb(p)); end $function$;
